if (!edit_mode)
{
    var _gp = pad >= 0 && gamepad_is_connected(pad);
    var _up = keyboard_check_pressed(vk_up);
    var _down = keyboard_check_pressed(vk_down);
    var _left = keyboard_check_pressed(vk_left);
    var _right = keyboard_check_pressed(vk_right);
    var _ok = keyboard_check_pressed(vk_enter);
    var _back = keyboard_check_pressed(vk_escape);
    var _all = false;
    var _reset = false;
    if (_gp)
    {
        _up = _up || gamepad_button_check_pressed(pad, gp_padu);
        _down = _down || gamepad_button_check_pressed(pad, gp_padd);
        _left = _left || gamepad_button_check_pressed(pad, gp_padl);
        _right = _right || gamepad_button_check_pressed(pad, gp_padr);
        _ok = _ok || gamepad_button_check_pressed(pad, gp_face1);
        _back = _back || gamepad_button_check_pressed(pad, gp_face2);
        _reset = gamepad_button_check_pressed(pad, gp_face3);
        _all = gamepad_button_check_pressed(pad, gp_face4);
    }
    if (obj_control_config_camera.screen == 0)
    {
        if (_left)
        {
            nav_col = 1;
        }
        if (_right)
        {
            nav_col = 0;
        }
        if (_up || _down)
        {
            audio_stop_sound(sfx_menu_tick);
            audio_play_sound(sfx_menu_tick, 10, false);
            if (nav_col == 0)
            {
                if (_up)
                {
                    nav_row--;
                }
                if (_down)
                {
                    nav_row++;
                }
                if (nav_row < 1)
                {
                    nav_row = 9;
                }
                if (nav_row > 9)
                {
                    nav_row = 1;
                }
            }
            else
            {
                if (_up)
                {
                    nav_btn--;
                }
                if (_down)
                {
                    nav_btn++;
                }
                if (nav_btn < 0)
                {
                    nav_btn = 2;
                }
                if (nav_btn > 2)
                {
                    nav_btn = 0;
                }
            }
        }
        if (_ok)
        {
            if (nav_col == 0)
            {
                keychange = nav_row;
                edit_mode = true;
                change_all = false;
                gp_held = true;
                audio_stop_sound(sfx_menu_confirm);
                audio_play_sound(sfx_menu_confirm, 10, false);
            }
            else if (nav_btn == 0)
            {
                with (obj_control_config_setall_button)
                {
                    event_perform(ev_mouse, ev_left_press);
                }
                gp_held = true;
            }
            else if (nav_btn == 1)
            {
                with (obj_control_config_exit_button)
                {
                    event_perform(ev_mouse, ev_left_press);
                }
            }
            else
            {
                with (obj_control_config_advanced_button)
                {
                    if (object_index == obj_control_config_advanced_button)
                    {
                        event_perform(ev_mouse, ev_left_press);
                    }
                }
                nav_adv = 0;
            }
        }
        else if (_all)
        {
            with (obj_control_config_setall_button)
            {
                event_perform(ev_mouse, ev_left_press);
            }
            gp_held = true;
        }
        else if (_reset)
        {
            with (obj_control_config_reset_all)
            {
                event_perform(ev_mouse, ev_left_press);
            }
        }
        else if (_back)
        {
            with (obj_control_config_exit_button)
            {
                event_perform(ev_mouse, ev_left_press);
            }
        }
        if (!edit_mode)
        {
            if (nav_col == 0)
            {
                image_index = nav_row;
            }
            else
            {
                image_index = 0;
            }
        }
    }
    else
    {
        if (_up)
        {
            nav_adv--;
            audio_stop_sound(sfx_menu_tick);
            audio_play_sound(sfx_menu_tick, 10, false);
        }
        if (_down)
        {
            nav_adv++;
            audio_stop_sound(sfx_menu_tick);
            audio_play_sound(sfx_menu_tick, 10, false);
        }
        if (nav_adv < 0)
        {
            nav_adv = 3;
        }
        if (nav_adv > 3)
        {
            nav_adv = 0;
        }
        if (_ok)
        {
            if (nav_adv == 0)
            {
                with (obj_control_config_disable_dpad)
                {
                    event_perform(ev_mouse, ev_left_press);
                }
            }
            else if (nav_adv == 1)
            {
                with (obj_control_config_disable_lstick)
                {
                    event_perform(ev_mouse, ev_left_press);
                }
            }
            else if (nav_adv == 2)
            {
                with (obj_control_config_reset_all)
                {
                    event_perform(ev_mouse, ev_left_press);
                }
            }
            else
            {
                with (obj_control_config_return)
                {
                    event_perform(ev_mouse, ev_left_press);
                }
                nav_col = 1;
                nav_btn = 2;
            }
        }
        else if (_back)
        {
            with (obj_control_config_return)
            {
                event_perform(ev_mouse, ev_left_press);
            }
            nav_col = 1;
            nav_btn = 2;
        }
    }
}

