if (mobile_device)
{
    var _tb_act = false;
    for (var _p = 0; _p < 4; _p++)
    {
        if (gamepad_is_connected(_p))
        {
            for (var _bb = 32769; _bb <= 32784; _bb++)
            {
                if (gamepad_button_check(_p, _bb))
                {
                    _tb_act = true;
                }
            }
            if (abs(gamepad_axis_value(_p, gp_axislh)) > 0.6 || abs(gamepad_axis_value(_p, gp_axislv)) > 0.6)
            {
                _tb_act = true;
            }
        }
    }
    var _tb_touch = false;
    for (var _dd = 0; _dd < 5; _dd++)
    {
        if (device_mouse_check_button(_dd, mb_left))
        {
            _tb_touch = true;
        }
    }
    if (_tb_act)
    {
        global.tb_pad_seen = true;
    }
    else if (_tb_touch)
    {
        global.tb_pad_seen = false;
    }
    global.tb_ov_show = false;
    if (global.touch_controls == 1)
    {
        global.tb_ov_show = true;
    }
    if (global.touch_controls == 0 && !global.tb_pad_seen)
    {
        global.tb_ov_show = true;
    }
    var _tb_w = display_get_width();
    var _tb_h = display_get_height();
    var _tb_sw = max((_tb_w - _tb_h) / 2, 0);
    var _tb_b = min(_tb_h * 0.2, max(_tb_sw * 0.3, _tb_h * 0.13));
    global.tb_ov_b = _tb_b;
    var _tb_cy = _tb_h * 0.64;
    var _tb_lx = max(_tb_sw * 0.5, _tb_b * 1.8);
    var _tb_rx = _tb_w - _tb_lx;
    var _tb_s = _tb_b * 1.1;
    global.tb_bx[0] = _tb_lx - _tb_s;
    global.tb_by[0] = _tb_cy;
    global.tb_bx[1] = _tb_lx + _tb_s;
    global.tb_by[1] = _tb_cy;
    global.tb_bx[2] = _tb_lx;
    global.tb_by[2] = _tb_cy - _tb_s;
    global.tb_bx[3] = _tb_lx;
    global.tb_by[3] = _tb_cy + _tb_s;
    global.tb_bx[4] = _tb_rx + _tb_s;
    global.tb_by[4] = _tb_cy;
    global.tb_bx[5] = _tb_rx;
    global.tb_by[5] = _tb_cy + _tb_s;
    global.tb_bx[6] = _tb_rx - _tb_s;
    global.tb_by[6] = _tb_cy;
    global.tb_bx[7] = _tb_rx;
    global.tb_by[7] = _tb_cy - _tb_s;
    global.tb_bx[8] = _tb_rx;
    global.tb_by[8] = _tb_h * 0.12;
    for (var _i = 0; _i < 8; _i++)
    {
        global.tb_bw[_i] = _tb_b * 1.1;
        global.tb_bh[_i] = _tb_b * 1.1;
    }
    global.tb_bw[8] = _tb_b * 1.7;
    global.tb_bh[8] = _tb_b * 0.8;
    for (var _i = 0; _i < 9; _i++)
    {
        var _prs = false;
        if (global.tb_ov_show)
        {
            for (var _dd = 0; _dd < 5; _dd++)
            {
                if (device_mouse_check_button(_dd, mb_left))
                {
                    var _mx = device_mouse_raw_x(_dd);
                    var _my = device_mouse_raw_y(_dd);
                    if (abs(_mx - global.tb_bx[_i]) <= (global.tb_bw[_i] * 0.5) && abs(_my - global.tb_by[_i]) <= (global.tb_bh[_i] * 0.5))
                    {
                        _prs = true;
                    }
                }
            }
        }
        if (_prs)
        {
            keyboard_key_press(global.tb_key[_i]);
            global.tb_dn[_i] = true;
        }
        else if (global.tb_dn[_i])
        {
            keyboard_key_release(global.tb_key[_i]);
            global.tb_dn[_i] = false;
        }
    }
}
